methods._updTimer:
_updTimer(time) {
    if (time == null) return;
    const L = this._L;
    const txt = fmtTime(time);
    if (txt !== L.timer) {
      L.timer = txt;
      this.timerTxt.textContent = tu(txt);
      if (time <= 10.001 && time > 0) this.timer.animate([{ transform: 'scale(1.3) rotate(-4deg)' }, { transform: 'scale(1)' }], BUMP);
    }
    const fin = time <= 10.001;
    if (fin !== L.fin) { L.fin = fin; this.timer.classList.toggle('is-final', fin); }
    const last = time <= 60.001 && !fin;
    if (last !== L.lastMin) { L.lastMin = last; this.timer.classList.toggle('is-last', last); }
  }

methods._updTurf:
_updTurf(dt) {
    this._turfT += dt;
    if (this._turfAcc > 0 && (this._turfT > 0.4 || this._turfAcc > 40)) {
      const n = Math.round(this._turfAcc);
      if (n >= 1) this._turfPop(n);
      this._turfAcc -= n;
      if (this._turfAcc < 0) this._turfAcc = 0;
      this._turfT = 0;
    }
    // total counts up toward the real value
    const tgt = this._turfTotal;
    if (this._turfShown < tgt) this._turfShown = Math.min(tgt, this._turfShown + Math.max(6, (tgt - this._turfShown) * 7) * dt);
    const txt = fmtInt(Math.floor(this._turfShown));
    if (txt !== this._L.turfTxt) {
      this._L.turfTxt = txt; this.turfNum.textContent = tu(txt);
    }
  }

methods._updSquads:
_updSquads(teams) {
    const L = this._L;
    for (let t = 0; t < 2; t++) {
      const team = teams[t];
      this._setTurfLead(t, team?.danger ? -1 : team?.leading ? 1 : 0);
      const ps = (team && team.players) || [];
      const icons = this.squads[t].children;
      for (let i = 0; i < 4; i++) {
        const p = ps[i];
        const el = icons[i];
        const k = `sq${t}${i}`;
        if (!p) { if (L[k] !== 'none') { L[k] = 'none'; el.classList.add('is-empty'); } continue; }
        const w = p.weapon || (this._actorFor(t, i) || {}).weaponId || 'shooter';
        const key = `${p.alive ? 1 : 0}|0|${p.specialReady ? 1 : 0}|${p.isSelf ? 1 : 0}|${w}`;
        if (L[k] === key) continue;
        const prev = L[k];
        L[k] = key;
        el.classList.remove('is-empty');
        if (el._w !== w) { el._w = w; el.querySelector('.iw-sq__w').innerHTML = weaponIcon(kindOf(w)); }
        const wasAlive = prev && prev !== 'none' ? prev[0] === '1' : true;
        const wasReady = prev && prev !== 'none' ? prev.split('|')[2] === '1' : false;
        el.classList.toggle('is-dead', !p.alive);
        el.classList.toggle('is-ready', !!p.specialReady && !!p.alive);
        el.classList.toggle('is-self', !!p.isSelf);
        el.querySelector('.iw-sq__n').textContent = '';
        if (wasAlive && !p.alive) {
          el.animate([{ transform: 'scale(1.4) rotate(-14deg)' }, { transform: 'scale(.92) rotate(4deg)', offset: 0.5 }, { transform: 'scale(1)' }], { duration: 420, easing: 'cubic-bezier(.34,1.6,.64,1)' });
          const ring = el.querySelector('.iw-sq__ring circle');
          ring.style.display = 'none';
          this._restart(el, 'is-dying');
        } else if (!wasAlive && p.alive) {
          el.animate([{ transform: 'translateY(-10px) scale(1.25)' }, { transform: 'none' }], BUMP);
          el.classList.remove('is-dying');
        }
        if (!wasReady && p.specialReady && p.alive) this._restart(el, 'is-readyflash');
      }
    }
  }

methods._updMap:
_updMap(m, dt) {
    const L = this._L, M = this._map;
    const show = !!(m && m.canvas);
    if (show !== L.mapShow) { L.mapShow = show; this.map.style.display = show ? '' : 'none'; if (!show) { this.mapDim.classList.remove('is-on'); M.open = false; } }
    if (!show) return;
    if (m.canvas !== this._mapCanvas) {
      this._mapCanvas = m.canvas;
      this.mapSlot.innerHTML = '';
      this.mapSlot.appendChild(m.canvas);
      m.canvas.classList.add('iw-map__canvas');
      L.mapBox = null;
    }
    // the big map only opens during live play (the controller's TAB state can stay latched through time's up)
    const target = m.expanded && (this.lab || !G.match || G.match.state === 'playing') ? 1 : 0;
    if (target !== L.mapExp) {
      L.mapExp = target;
      this.mapDim.classList.toggle('is-on', !!target);
      this.map.classList.toggle('is-expanded', !!target);
      this.el.classList.toggle('is-mapopen', !!target);
      M.open = !!target;
      if (M.open) { M.cx = M.sx ?? 0.5; M.cy = M.sy ?? 0.8; M.hover = -1; this._snd('ui_click', { volume: 0.5 }); this.map.style.pointerEvents = 'auto'; }
      else { this.map.style.pointerEvents = ''; }
    }
    const k = 190, c = 21;
    const a = k * (target - this._mapT) - c * this._mapV;
    this._mapV += a * Math.min(dt, 0.05); this._mapT += this._mapV * Math.min(dt, 0.05);
    if (Math.abs(target - this._mapT) < 0.001 && Math.abs(this._mapV) < 0.001) { this._mapT = target; this._mapV = 0; }
    const W = innerWidth, H = innerHeight;
    const u = Math.min(W / 100, (H * 1.7778) / 100);
    const asp = (m.canvas.width || 1) / (m.canvas.height || 1);
    const small = 14.5 * u, large = Math.min(H * 0.78, W * 0.6);
    const w0 = asp >= 1 ? small : small * asp, h0 = asp >= 1 ? small / asp : small;
    const w1 = asp >= 1 ? large : large * asp, h1 = asp >= 1 ? large / asp : large;
    const t = this._mapT;
    const bw = lerp(w0, w1, t), bh = lerp(h0, h1, t);
    // touch: the move stick owns the bottom-left, so the small map lives top-left (tap it to open the big map)
    const touchUI = G.input?.lastDevice === 'touch';
    const sb = touchUI ? (G.input?.mobile?._safeBox || null) : null;
    const x0 = touchUI ? Math.max(2.2 * u, (sb?.l ?? 8) + 4) : 2.2 * u, y0 = touchUI ? Math.max(1.6 * u, (sb?.t ?? 6) + 4) : H - 2.2 * u - h0;
    const x = lerp(x0, (W - w1) / 2, t), y = lerp(y0, (H - h1) / 2 + u * 1.2, t);
    const inside = (W - w1) / 2 < 22 * u;
    if (inside !== L.lgIn) { L.lgIn = inside; this.mapLegend.classList.toggle('is-inside', inside); }
    const box = `${x.toFixed(1)},${y.toFixed(1)},${bw.toFixed(1)},${bh.toFixed(1)}`;
    if (box !== L.mapBox) {
      L.mapBox = box;
      const st = this.map.style;
      st.transform = `translate3d(${x.toFixed(1)}px,${y.toFixed(1)}px,0)`;
      st.width = bw.toFixed(1) + 'px'; st.height = bh.toFixed(1) + 'px';
    }
    // dots
    const ps = m.players || [];
    const ca = L.ca || '#ff8a14', cb = L.cb || '#2f5bff';
    for (let i = 0; i < this.mapDots.length; i++) {
      const d = this.mapDots[i], p = ps[i];
      const dk = `md${i}`;
      if (!p) { if (L[dk] !== 'x') { L[dk] = 'x'; d.style.display = 'none'; } continue; }
      const px = clamp(+p.x || 0) * bw, py = clamp(+p.y || 0) * bh;
      if (p.isSelf) { M.sx = clamp(+p.x || 0); M.sy = clamp(+p.y || 0); }
      const key = `${px.toFixed(1)}|${py.toFixed(1)}|${(+p.yaw || 0).toFixed(2)}|${p.alive === false ? 0 : 1}|${p.isSelf ? 1 : 0}|${p.team}`;
      if (L[dk] === key) continue;
      const prev = L[dk] || '';
      L[dk] = key;
      if (prev === 'x' || !prev) d.style.display = '';
      const sk = `${p.isSelf ? 1 : 0}|${p.alive === false ? 0 : 1}|${p.team}`;
      if (d._sk !== sk) {
        d._sk = sk;
        d.className = 'iw-mdot' + (p.isSelf ? ' is-self' : '') + (p.alive === false ? ' is-dead' : '') + (p.team !== this._myTeam() ? ' is-enemy' : '');
        d.style.setProperty('--c', p.team !== this._myTeam() ? cb : ca);
      }
      d.style.transform = `translate3d(${px.toFixed(1)}px,${py.toFixed(1)}px,0) rotate(${p.isSelf ? (+p.yaw || 0).toFixed(3) : 0}rad)`;
    }
    this._updBeacons(bw, bh, dt, u);
  }

methods._updMarkers:
_updMarkers(ms) {
    const L = this._L;
    ms = ms || [];
    let byName = this._byName;
    const actors = this._actors();
    if (!this.lab) this._actorRefsMatch = G.match;
    if (!byName || this._byNameN !== actors.length || this._byNameA !== actors[0]) {
      byName = this._byName = new Map(actors.map((a) => [a.name, a]));
      this._byNameN = actors.length; this._byNameA = actors[0];
    }
    for (let i = 0; i < this.markers.length; i++) {
      const el = this.markers[i], m = ms[i];
      const k = `mk${i}`;
      if (!m) { if (L[k] !== 'x') { L[k] = 'x'; el.style.display = 'none'; } continue; }
      const on = !!m.onScreen;
      const ac = byName.get(m.name);
      const ready = typeof m.specialReady === 'boolean' ? m.specialReady : !!(ac && ac.specialReady && ac.specialReady());
      const w = m.weapon || (ac && ac.weaponId);
      const far = m.dist != null ? clamp((m.dist - 14) / 20, 0, 1) : 0;
      const key = `${(+m.x).toFixed(0)}|${(+m.y).toFixed(0)}|${on ? 1 : 0}|${on ? 0 : (+m.angle || 0).toFixed(2)}|${m.name}|${m.color}|${ready ? 1 : 0}|${far.toFixed(1)}|${w || ''}`;
      if (L[k] === key) continue;
      const prev = L[k];
      L[k] = key;
      if (prev === 'x' || !prev) el.style.display = '';
      if (el._name !== m.name || el._weapon !== w) {
        el._name = m.name; el._weapon = w;
        el.querySelector('.iw-mk__tag b').textContent = m.name || '';
        el.querySelector('.iw-mk__w').innerHTML = w ? weaponIcon(kindOf(w)) : '';
      }
      const col = toHex(m.color, '#ffffff');
      if (el._col !== col) { el._col = col; colorVars(el, 'c', col); }
      if (el._on !== on) { el._on = on; el.classList.toggle('is-off', !on); }
      if (el._ready !== ready) { el._ready = ready; el.classList.toggle('is-ready', ready); }
      el.style.setProperty('--far', far.toFixed(2));
      el.style.transform = `translate3d(${(+m.x).toFixed(1)}px,${(+m.y).toFixed(1)}px,0)`;
      if (!on) el.lastChild.style.transform = `rotate(${(+m.angle || 0).toFixed(3)}rad)`;
    }
  }

methods.forward:
forward(out) {
    const cp = Math.cos(this.pitch);
    return out.set(Math.sin(this.yaw) * cp, Math.sin(this.pitch), Math.cos(this.yaw) * cp);
  }

methods._follow:
_follow(dt) {
    const a = this.target, cam = this.camera;
    const squid = a.form === 'squid';
    const af = a.anim.form;
    const swim = af === 'swim' || af === 'climb';
    const sj = a.superJumpState;
    const flying = !!(sj && sj.phase === 'flight');
    const special = !!a.specialActive;
    const p = a.visualPos ? a.visualPos(_v3) : _v3.copy(a.pos);
    // ---- pivot height above the feet (form changes glide)
    const hT = swim ? 1.15 : squid ? 1.3 : 1.85;
    const h = this.hgt.step(hT, 11, dt);
    // ---- horizontal: critically-damped with 72 % velocity feed-forward (fluid, no persistent lag)
    const omegaH = flying ? 20 : 30, lead = 0.72 * 2 / omegaH;
    const fwd = this.forward(_fwd);
    _right.set(-Math.cos(this.yaw), 0, Math.sin(this.yaw));   // camera right on the ground plane
    // strafe look-ahead: a hair more view where you're heading sideways
    const lat = a.vel.x * _right.x + a.vel.z * _right.z;
    const sideT = clamp(lat * 0.045, -0.32, 0.32) * (flying ? 0 : 1);
    const so = this.side.step(sideT, 3.2, dt);
    const tx = p.x + a.vel.x * lead + _right.x * so, tz = p.z + a.vel.z * lead + _right.z * so;
    // snap if the target teleported (respawn, NaN recovery)
    const ty = p.y + h;
    if (Math.abs(this.sx.x - p.x) + Math.abs(this.sz.x - p.z) > 6 || Math.abs(this.sy.x - ty) > 6) {
      this.sx.reset(p.x); this.sz.reset(p.z); this.sy.reset(ty); this._lastTY = null; this._vyF = 0;
    }
    this.sx.step(tx, omegaH, dt); this.sz.step(tz, omegaH, dt);
    // ---- vertical: firm on the ground (ramps, steps), soft through ordinary jumps, firm again for falls/super jumps
    // vertical velocity for the feed-forward, low-passed: a raw per-frame difference turned tiny contact wobbles and
    // uneven frame times into a vertical buzz
    const fresh = this._lastTY === null || dt <= 0;
    const vyRaw = fresh ? 0 : clamp((ty - this._lastTY) / dt, -30, 30);
    this._lastTY = ty;
    this._vyF = fresh ? 0 : damp(this._vyF || 0, vyRaw, 30, dt);
    const vyT = this._vyF;
    let omegaV = 13, leadV = 0.5;
    if (a.grounded || a.climbing) this._takeoffY = p.y;
    if (!a.grounded && !a.climbing) {
      if (flying || special) { omegaV = 16; leadV = 0.85; }
      else if (p.y < (this._takeoffY ?? p.y) - 0.25) { omegaV = 15; leadV = 0.8; }   // dropping below where we left the ground: follow the fall
      else { omegaV = 7.5; leadV = 0.25; }                                  // a hop: keep the horizon calm
    }
    this.sy.step(ty + vyT * leadV * 2 / omegaV, omegaV, dt);
    // ---- landing dip (lightly under-damped: one soft settle with weight, no bob)
    if (a.landT !== undefined) {
      if (a.landT < this._landSeen - 1e-6 && a.landSpeed > 4) this.dipS.v -= clamp((a.landSpeed - 4) * 0.045, 0, 0.45);
      this._landSeen = a.landT;
    }
    const dip = clamp(stepDamped(this.dipS, 0, 13, 0.82, dt), -0.3, 0.12);
    this.pivot.set(this.sx.x, this.sy.x + dip, this.sz.x);
    this.pivotY = this.pivot.y;
    // ---- super jump: swing toward the landing spot and look down on it during the descent; settle after landing
    const hs = Math.hypot(a.vel.x, a.vel.z);
    if (flying) {
      const dx = sj.to.x - sj.from.x, dz = sj.to.z - sj.from.z;
      if (dx * dx + dz * dz > 1) this.yaw = dampAngle(this.yaw, Math.atan2(dx, dz), 3.5, dt);
      const k = clamp(sj.t / sj.dur, 0, 1);
      this.pitch = damp(this.pitch, lerp(-0.3, -0.75, clamp((k - 0.35) / 0.5, 0, 1)), 4, dt);
      this._sjWasFlight = true;
    } else if (this._sjWasFlight) { this._sjWasFlight = false; this._sjLandT = 0; }
    if (this._sjLandT < 0.45) { this._sjLandT += dt; if (this.pitch < -0.2) this.pitch = damp(this.pitch, -0.16, 7, dt); }
    // ---- FOV: swim speed, super jump, a touch on takeoff; charger zoom
    let fk = 0;
    if (swim) fk = clamp((hs - 6) * 1.1, 0, 7);
    else if (flying) fk = 6;
    else if (!a.grounded && a.vel.y > 2) fk = 1.2;
    this.fovKick = damp(this.fovKick, fk, 5, dt);
    const charging = updateScopeZoom(this, a, dt);
    this.scopeK = damp(this.scopeK, chargerScopeFactor(a.weapon, charging, a.weaponRunner?.charging), 16, dt);
    // Unscoped chargers stay in the normal third-person view; a scoped charger
    // moves the actual camera in to its eyepiece, not just the FOV slider.
    // Source updateScopeZoom owns the scope gauge; do not overwrite it.
    // ---- boom length: soft probe, fast in / slow out
    let want = (squid ? 4.1 : this.dist) - charging * 0.18;
    want = lerp(want, 0.5, this.scopeK);
    if (swim) want += clamp((hs - 6) / 6, 0, 1) * 0.35;
    if (flying) want += 1.2;
    this.wantDist = damp(this.wantDist, want, 6, dt);
    // Super-jump yaw/pitch may have changed since the pivot calculation.
    this.forward(fwd);
    _right.set(-Math.cos(this.yaw), 0, Math.sin(this.yaw));
    _back.copy(fwd).negate();
    // #862: Physics.cameraProbe only queries the current level broadphase. Reuse its exact
    // result while the follow probe is effectively stationary (1 mm pivot/want-distance
    // tolerance and 0.001 unit-vector delta); keep a short bound for
    // geometry edits that preserve the Level/collection objects.
    const _qcPhysics = G.physics, _qcLevel = _qcPhysics.level;
    const _qcOld = this._inkwaveCameraProbeCache;
    const _qcAge = _qcOld ? _qcOld.age + (Number.isFinite(dt) ? Math.max(0, dt) : 0) : 0;
    const _qcPX = _qcOld ? this.pivot.x - _qcOld.px : Infinity;
    const _qcPY = _qcOld ? this.pivot.y - _qcOld.py : Infinity;
    const _qcPZ = _qcOld ? this.pivot.z - _qcOld.pz : Infinity;
    const _qcBX = _qcOld ? _back.x - _qcOld.bx : Infinity;
    const _qcBY = _qcOld ? _back.y - _qcOld.by : Infinity;
    const _qcBZ = _qcOld ? _back.z - _qcOld.bz : Infinity;
    const _qcChanged = !_qcOld || _qcOld.target !== a || _qcOld.mode !== this.mode ||
      _qcOld.level !== G.level || _qcOld.physics !== _qcPhysics ||
      _qcOld.probe !== _qcPhysics.cameraProbe || _qcOld.raycast !== _qcPhysics.raycast ||
      _qcOld.collisionLevel !== _qcLevel || _qcOld.blocks !== _qcLevel?.blocks ||
      _qcOld.hash !== _qcLevel?.hash || _qcOld.blockStamp !== _qcLevel?.blockStamp ||
      _qcPX * _qcPX + _qcPY * _qcPY + _qcPZ * _qcPZ > 0.000001 ||
      _qcBX * _qcBX + _qcBY * _qcBY + _qcBZ * _qcBZ > 0.000001 ||
      Math.abs(this.wantDist - _qcOld.want) > 0.001 ||
      (this.wantDist !== _qcOld.want &&
       (_qcOld.hard !== _qcOld.want || _qcOld.soft !== _qcOld.want));
    if (_qcChanged || _qcAge >= 0.25) {
      _qcPhysics.cameraProbe(this.pivot, _back, this.wantDist, 0.62, _probe);
      this._inkwaveCameraProbeCache = { target: a, mode: this.mode, level: G.level,
        physics: _qcPhysics, probe: _qcPhysics.cameraProbe, raycast: _qcPhysics.raycast,
        collisionLevel: _qcLevel, blocks: _qcLevel?.blocks, hash: _qcLevel?.hash,
        blockStamp: _qcLevel?.blockStamp, px: this.pivot.x, py: this.pivot.y, pz: this.pivot.z,
        bx: _back.x, by: _back.y, bz: _back.z, want: this.wantDist,
        hard: _probe.hard, soft: _probe.soft, floor: _probe.floor, age: 0 };
    } else {
      _qcOld.age = _qcAge;
      // A free probe is equal to its sampled request distance. Keep that
      // endpoint live when a sub-millimetre zoom step reuses the cache.
      _probe.hard = _qcOld.hard === _qcOld.want ? this.wantDist : _qcOld.hard;
      _probe.soft = _qcOld.soft === _qcOld.want ? this.wantDist : _qcOld.soft;
      _probe.floor = _qcOld.floor;
    }
    const tgt = _probe.soft;
    // fast in / slow out. The lens may trail a fast-closing obstacle for a few frames (bounded to 1.2 m past the line of
    // sight — back faces cull and the level's see-through dither covers the brief occlusion) instead of popping.
    const deep = clamp((this.boom.x - _probe.hard) / 1.0, 0, 1);   // the further past the line of sight, the faster in
    this.boom.step(tgt, tgt < this.boom.x ? 22 + 26 * deep : 3.6, dt);
    enforceBoomClearance(this.boom, _probe.hard);
    this.curDist = this.boom.x;
    cam.position.copy(this.pivot).addScaledVector(fwd, -this.curDist + this.scopeK * 0.55);
    cam.position.y += 0.15;
    // keep the lens off the floor under it (only real floors well below the pivot — not wall tops at head height)
    const gy = G.level?.groundHeight(cam.position.x, cam.position.z, cam.position.y + 0.2) ?? -Infinity;
    const liftT = gy > -Infinity && gy < this.pivot.y - 0.6 ? Math.max(0, gy + 0.24 - cam.position.y) : 0;
    this.lensLift.step(liftT, liftT > this.lensLift.x ? 34 : 7, dt);
    cam.position.y += this.lensLift.x;
    // ---- over-the-shoulder when the boom is forced short (wall right behind you): ease the lens to the right so your
    // head never sits on the crosshair; never slide it into a wall on that side
    const closeK = clamp((2.8 - this.curDist) / 1.8, 0, 1);
    const SH0 = 0.28;   // persistent right-shoulder framing; not a pinned S3 value
    let shT = SH0 + (0.55 - SH0) * closeK * closeK * (3 - 2 * closeK);
    let shMax = Infinity;
    if (shT > 0.01 && G.physics) {
      const hr = G.physics.raycast(cam.position, _right, Math.max(shT, this.shoulder || 0) + 0.25, _hit, true);
      if (hr.hit) { shMax = Math.max(0, hr.dist - 0.25); shT = Math.min(shT, shMax); }
    }
    this.shoulder = damp(this.shoulder || 0, shT, 8, dt);
    if (this.shoulder > shMax) this.shoulder = shMax;
    if (this.shoulder > 1e-3) cam.position.addScaledVector(_right, this.shoulder);
    // ---- visual recoil (pitch kick up), exact critically-damped spring
    this.kick = clamp(this.kickS.step(0, 22, dt), -0.01, 0.035);
    // ---- orientation = the aim, exactly
    _v2.copy(this.pivot).addScaledVector(fwd, 10);
    _v2.y += 0.15;
    if (this.shoulder > 1e-3) _v2.addScaledVector(_right, this.shoulder);   // parallel shift: aim direction unchanged
    cam.up.set(0, 1, 0);
    cam.lookAt(_v2);
    if (Math.abs(this.kick) > 1e-6) cam.rotateX(this.kick);
  }

